"""Two Sum II - Input Array Is Sorted — Two Pointer.

Because the array is sorted, shrink the window from whichever end is wrong:
a sum that is too small can only grow by moving `lo` right, a sum that is too
large can only shrink by moving `hi` left.

Time: O(n)   Space: O(1)
"""
from typing import List


class Solution:
    def twoSum(self, numbers: List[int], target: int) -> List[int]:
        lo, hi = 0, len(numbers) - 1
        while lo < hi:
            total = numbers[lo] + numbers[hi]
            if total == target:
                return [lo + 1, hi + 1]  # answer is 1-indexed
            if total < target:
                lo += 1
            else:
                hi -= 1
        return []
